"use client"; import { useState } from "react"; import Link from "next/link"; import { useRouter } from "next/navigation"; import { supabase } from "@/lib/supabase"; import { Button } from "@/components/ui/button"; import { Input } from "@/components/ui/input"; import { Label } from "@/components/ui/label";
export default function Login(){const router=useRouter();const [email,setEmail]=useState("");const [pw,setPw]=useState("");const [err,setErr]=useState("");const [loading,setLoading]=useState(false);
 async function onSubmit(e:React.FormEvent){e.preventDefault();setErr("");setLoading(true);const {error}=await supabase.auth.signInWithPassword({email,password:pw});setLoading(false);if(error){setErr(error.message);return;}router.replace("/app/dashboard");}
 return <div className="flex min-h-screen items-center justify-center bg-[#050807] px-4 text-zinc-100"><div className="w-full max-w-md rounded-lg border border-white/[0.08] bg-[#0F1511] p-7"><Link href="/" className="font-display font-semibold">ZEVQYN</Link><h1 className="mt-5 text-2xl font-semibold tracking-tight">Welcome back</h1><p className="mt-1 text-sm text-zinc-400">Sign in to your workspace.</p><form onSubmit={onSubmit} className="mt-6 space-y-4"><div className="space-y-2"><Label htmlFor="email">Email</Label><Input id="email" type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email"/></div><div className="space-y-2"><Label htmlFor="pw">Password</Label><Input id="pw" type="password" value={pw} onChange={e=>setPw(e.target.value)} required autoComplete="current-password"/></div>{err&&<p className="text-sm text-red-300" role="alert">{err}</p>}<Button type="submit" className="w-full" disabled={loading}>{loading?"Signing in…":"Sign in"}</Button></form><p className="mt-5 text-center text-sm text-zinc-400">No account? <Link href="/register" className="text-indigo-300">Create one</Link></p></div></div>;}
